    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "How can robotics data help insurers underwrite autonomy?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Scenario-based evaluation data shows how an autonomous system performs in the situations that drive claims, with provenance records that let an underwriter trust and compare results across software versions."
        }
      },
      {
        "@type": "Question",
        "name": "What is evidence-grade data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's data with traceable provenance, organized by risk-relevant scenarios, held out from training, reproducible on new versions, and realistic enough to reflect actual claims conditions."
        }
      },
      {
        "@type": "Question",
        "name": "Do you collect data for property damage inspection AI?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We capture drone imagery and 3D scans across roof and facade materials, damage types, and lighting, planned around the resolution the model needs."
        }
      },
      {
        "@type": "Question",
        "name": "Can robotics companies use this to get insurance coverage?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. A structured, scenario-based performance report backed by traceable data gives underwriters something concrete to evaluate, which can shorten the path to coverage."
        }
      },
      {
        "@type": "Question",
        "name": "Is your evaluation independent from the robot developer?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Evaluation sets can be collected separately from training data and from the team that built the system. The level of independence is agreed during scoping."
        }
      },
      {
        "@type": "Question",
        "name": "What's the evidence behind autonomy reducing claims?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "A Swiss Re study of Waymo's 25.3 million autonomous miles found an 88% reduction in property damage claims and a 92% reduction in bodily injury claims compared with human drivers."
        }
      }
    ]
  }
